BEGIN;

UPDATE public.catalog_products SET description = $q$Compact 3,000mAh pocket power bank with built-in multi-cable (USB-C and USB-A inputs, Lightning and USB-C outputs), so the unit recharges itself from the mains while simultaneously charging a smartphone, headset, GoPro, or similar device. Made from 30% GRS-certified recycled plastic (22% RABS, 7% RTPE) and shipped in FSC-certified paper packaging from sustainably managed forests. Suited to tech-focused corporate gifting and sustainability-led campaigns; backed by a 2-year warranty.$q$ WHERE slug = 'gamma-lite';
UPDATE public.catalog_product_specifications SET specifications = $q${}$q$::jsonb, updated_at = now() WHERE catalog_product_id = (SELECT id FROM public.catalog_products WHERE slug = 'gamma-lite');
UPDATE public.ava_direct_product_context SET differentiators = $q$Compact 3,000mAh pocket power bank (ABS plus lithium battery) with a built-in multi-cable that recharges itself from the mains while charging a phone or device, 30% GRS-certified recycled plastic, FSC packaging, and a 2-year warranty. Unlike Mr Bio (a recycled cable with no battery), this carries its own charge.$q$, upsell_framing_example = $q$The Gamma Lite is worth suggesting when the customer wants portable power rather than just a cable: a 3,000mAh pocket power bank with the charging lead built in, so recipients can top up away from the mains. Suggest the Mr Bio cable instead when they only need a recycled charging lead, not a battery.$q$ WHERE slug = 'gamma-lite';

UPDATE public.catalog_products SET description = $q$5,000mAh portable power bank with 15W fast charging and a built-in smart-touch LED flashlight, capable of recharging a typical smartphone around twice per cycle. Suited to everyday corporate gifting, conference welcome packs, and safety or emergency kits where the flashlight adds practical utility. CE, FCC, RoHS, and Prop 65 compliant.$q$ WHERE slug = 'ice-p';
UPDATE public.catalog_product_specifications SET specifications = $q${}$q$::jsonb, updated_at = now() WHERE catalog_product_id = (SELECT id FROM public.catalog_products WHERE slug = 'ice-p');
UPDATE public.ava_direct_product_context SET differentiators = $q$5,000mAh power bank with 15W fast charging and a built-in smart-touch LED flashlight, recharging a typical phone around twice per cycle. The flashlight adds practical utility for safety and emergency use.$q$, upsell_framing_example = $q$The Ice P is worth suggesting where a built-in flashlight adds practical value to a tech giveaway, especially conference packs and safety or emergency kits where the safety angle resonates.$q$ WHERE slug = 'ice-p';

UPDATE public.catalog_products SET description = $q$Suitcase-shaped international travel adapter covering 150+ countries via swap-in US, UK, EU, and AUS plugs, with two 25W USB-C ports for fast charging and a 15W USB-A port that together power multiple devices simultaneously. Built from 65% recycled flame-retardant R-ABS with safety shutters and an integrated fuse, and shipped with a generous imprint area suited to executive travel programs, incentive trips, and premium welcome kits. CE, FCC, RoHS, and Prop 65 compliant.$q$ WHERE slug = 'luggie';
UPDATE public.catalog_product_specifications SET specifications = $q${}$q$::jsonb, updated_at = now() WHERE catalog_product_id = (SELECT id FROM public.catalog_products WHERE slug = 'luggie');
UPDATE public.ava_direct_product_context SET differentiators = $q$International travel adapter covering 150+ countries with swap-in US, UK, EU, and AUS plugs, two 25W USB-C ports and a 15W USB-A port, built from 65% recycled flame-retardant R-ABS with a generous imprint area. A premium gift for higher-value contacts.$q$, upsell_framing_example = $q$The Luggie is worth considering if the client wants a premium gift for higher-value contacts: a recycled international travel adapter that covers 150+ countries.$q$ WHERE slug = 'luggie';

UPDATE public.catalog_products SET description = $q$Multi-charging cable with dual USB-A and USB-C inputs and three output tips (Micro USB, Lightning, and USB-C) covering Apple, Android, and modern Type-C devices in one unit. Constructed from 61% recycled material by weight, with a recycled-plastic housing and DuPont Tyvek cable jacket, shipped in FSC-certified paper packaging. An eco-conscious tech giveaway suited to sustainability-led corporate gifting and conference delegate bags.$q$ WHERE slug = 'mr-bio';
UPDATE public.catalog_product_specifications SET specifications = $q${}$q$::jsonb, updated_at = now() WHERE catalog_product_id = (SELECT id FROM public.catalog_products WHERE slug = 'mr-bio');
UPDATE public.ava_direct_product_context SET differentiators = $q$Multi-charging cable, 61% recycled by weight with a recycled-plastic housing, DuPont Tyvek jacket, and FSC-certified paper packaging. Three output tips cover Apple, Android, and USB-C in one unit.$q$, upsell_framing_example = $q$The Mr Bio cable is worth suggesting when sustainability matters: 61% recycled with FSC packaging, which lands well with eco-conscious corporate gifting.$q$ WHERE slug = 'mr-bio';

UPDATE public.catalog_products SET description = $q$2-metre multi-charging cable with dual USB-A and USB-C inputs and dual USB-C and Lightning outputs, delivering up to 60W fast charging and data transfer for phones, tablets, and compatible laptops. Made from 53% GRS-certified recycled plastic with a central logo hub for branding and a heart-shaped indicator that lights green in fast-charge mode. CarPlay compatible and compliant with CE, FCC, RoHS, and Prop 65.$q$ WHERE slug = 'mr-bio-pd-long';
UPDATE public.catalog_product_specifications SET specifications = $q${}$q$::jsonb, updated_at = now() WHERE catalog_product_id = (SELECT id FROM public.catalog_products WHERE slug = 'mr-bio-pd-long');
UPDATE public.ava_direct_product_context SET differentiators = $q$2-metre multi-charging cable, 53% GRS-certified recycled plastic, up to 60W fast charging and data transfer, a central logo hub for branding, and a heart indicator that lights green in fast-charge mode. CarPlay compatible.$q$, upsell_framing_example = $q$The Mr Bio PD Long is worth suggesting for a premium eco tech gift, with 60W fast charging and a 2-metre recycled cable.$q$ WHERE slug = 'mr-bio-pd-long';

UPDATE public.catalog_products SET description = $q$Multi-head charging cable with several connector tips built into one unit, so a single cable charges a range of phones and devices. Made from recycled ocean-reclaimed material. Suited to travel-heavy corporate clients, event delegate kits, and tech-sector promotional campaigns.$q$ WHERE slug = 'ocean-octopus';
UPDATE public.catalog_product_specifications SET specifications = $q${}$q$::jsonb, updated_at = now() WHERE catalog_product_id = (SELECT id FROM public.catalog_products WHERE slug = 'ocean-octopus');
UPDATE public.ava_direct_product_context SET differentiators = $q$Multi-head charging cable (no battery) with several connector tips built into one unit, so one cable charges a range of phones and devices. Made from recycled ocean-reclaimed material. A PGifts Direct hero product with live Designer previews.$q$, upsell_framing_example = $q$The Ocean Octopus is worth suggesting when the customer wants one charging cable that suits everyone's phone: several connector tips in one unit, made from recycled ocean-reclaimed material. It is a cable, not a power bank, so suggest the Gamma Lite or Ice P if they need portable power.$q$ WHERE slug = 'ocean-octopus';

UPDATE public.catalog_products SET description = $q$Compact version of the Ocean Octopus multi-head charging cable, sized to fit in a pocket or laptop bag for on-the-go charging. Made from recycled ocean-reclaimed material. Suited to conference welcome packs and lower-cost tech giveaways.$q$ WHERE slug = 'octopus-mini';
UPDATE public.catalog_product_specifications SET specifications = $q${}$q$::jsonb, updated_at = now() WHERE catalog_product_id = (SELECT id FROM public.catalog_products WHERE slug = 'octopus-mini');
UPDATE public.ava_direct_product_context SET differentiators = $q$Compact, pocket-sized version of the Ocean Octopus multi-head charging cable (no battery), made from recycled ocean-reclaimed material, at a lower price point than the full Ocean Octopus.$q$, upsell_framing_example = $q$The Octopus Mini is worth suggesting for a compact, lower-cost tech giveaway: a pocket-sized multi-head charging cable made from recycled ocean-reclaimed material. It has no battery.$q$ WHERE slug = 'octopus-mini';

